fn days_to_next_sunday(day: &str) -> i8 {
    let days = match day {
        "SUN" => 0,
        "MON" => 1,
        "TUE" => 2,
        "WED" => 3,
        "THU" => 4,
        "FRI" => 5,
        "SAT" => 6,
        _ => panic!("Invalid day abbreviation"), // This should not happen as per problem statement
    };

    if days == 0 {
        7 // If today is Sunday, return 7 days until the next Sunday
    } else {
        (7 - days) as i8 // Calculate days until next Sunday
    }
}